  dsx = xi / -cx\n    else:\n        dsx = (nx - 1 - xi) / cx\n    if cy == 0:\n        dsy = np.inf\n    elif cy < 0:\n        dsy = yi / -cy\n    else:\n        dsy = (ny - 1 - yi) / cy\n    ds = min(dsx, dsy)\n    xyf_traj.append((xi + cx * ds, yi + cy * ds))\n    return ds, xyf_traj\n\n\n# Utility functions\n# ========================\n\ndef interpgrid(a, xi, yi):\n    \"\"\"Fast 2D, linear interpolation on an integer grid\"\"\"\n\n    Ny, Nx = np.shape(a)\n    if isinstance(xi, np.ndarray):\n        x = xi.astype(int)\n        y = yi.astype(int)\n        # Check that xn, yn don't exceed max index\n        xn = np.clip(x + 1, 0, Nx - 1)\n        yn = np.clip(y + 1, 0, Ny - 1)\n    else:\n        x = int(xi)\n        y = int(yi)\n        # conditional is faster than clipping for integers\n        if x == (Nx - 1):\n            xn = x\n        else:\n            xn = x + 1\n        if y == (Ny - 1):\n            yn = y\n        else:\n            yn = y + 1\n",
/testbed/evaluations/codex-noexec/gpt-5.4/matplotlib_qa/streamplot_integrate_stotal_nonneg_invariant_suite/traj.json:225:        "aggregated_output": "    def _update_trajectory(self, xm, ym, broken_streamlines=True):\n        \"\"\"\n        Update current trajectory position in mask.\n\n        If the new position has already been filled, raise `InvalidIndexError`.\n        \"\"\"\n        if self._current_xy != (xm, ym):\n            if self[ym, xm] == 0:\n                self._traj.append((ym, xm))\n                self._mask[ym, xm] = 1\n                self._current_xy = (xm, ym)\n            else:\n                if broken_streamlines:\n                    raise InvalidIndexError\n                else:\n                    pass\n\n\nclass InvalidIndexError(Exception):\n    pass\n\n\nclass TerminateTrajectory(Exception):\n    pass\n\n\n# Integrator definitions\n# =======================\n\ndef _get_integrator(u, v, dmap, minlength, maxlength, integration_direction):\n\n    # rescale velocity onto grid-coordinates for integrations.\n    u, v = dmap.data2grid(u, v)\n\n    # speed (path length) will be in axes-coordinates\n    u_ax = u / (dmap.grid.nx - 1)\n    v_ax = v / (dmap.grid.ny - 1)\n    speed = np.ma.sqrt(u_ax ** 2 + v_ax ** 2)\n\n    def forward_time(xi, yi):\n        if not dmap.grid.within_grid(xi, yi):\n            raise OutOfBounds\n        ds_dt = interpgrid(speed, xi, yi)\n        if ds_dt == 0:\n            raise TerminateTrajectory()\n        dt_ds = 1. / ds_dt\n        ui = interpgrid(u, xi, yi)\n        vi = interpgrid(v, xi, yi)\n        return ui * dt_ds, vi * dt_ds\n\n    def backward_time(xi, yi):\n        dxi, dyi = forward_time(xi, yi)\n        return -dxi, -dyi\n\n    def integrate(x0, y0, broken_streamlines=True):\n        \"\"\"\n        Return x, y grid-coordinates of trajectory based on starting point.\n\n        Integrate both forward and backward in time from starting point in\n        grid coordinates.\n\n        Integration is terminated when a trajectory reaches a domain boundary\n        or when it crosses into an already occupied cell in the StreamMask. The\n        resulting trajectory is None if it is shorter than `minlength`.\n        \"\"\"\n\n        stotal, xy_traj = 0., []\n\n        try:\n            dmap.start_trajectory(x0, y0, broken_streamlines)\n        except InvalidIndexError:\n            return None\n        if integration_direction in ['both', 'backward']:\n            s, xyt = _integrate_rk12(x0, y0, dmap, backward_time, maxlength,\n                                     broken_streamlines)\n            stotal += s\n            xy_traj += xyt[::-1]\n\n        if integration_direction in ['both', 'forward']:\n            dmap.reset_start_point(x0, y0)\n            s, xyt = _integrate_rk12(x0, y0, dmap, forward_time, maxlength,\n                                     broken_streamlines)\n            stotal += s\n            xy_traj += xyt[1:]\n\n        if stotal > minlength:\n            return np.broadcast_arrays(xy_traj, np.empty((1, 2)))[0]\n        else:  # reject short trajectories\n            dmap.undo_trajectory()\n            return None\n\n    return integrate\n\n\nclass OutOfBounds(IndexError):\n    pass\n\n\n",
